      { icone: "🌾", titre: "Fariner", detail: "Roulez chaque papa dans la farine et laissez-les 15 minutes au frais.", badge: null },
      { icone: "🔥", titre: "Frire", detail: "Faites frire à 180°C jusqu'à brun doré, en les retournant. Servez avec de la salsa criolla. Les papas rellenas de Lima !", badge: null }
